package main

import (
	"bufio"
	"fmt"
	"os"
)

func maxInt(vals ...int) int {
	maxVal := vals[0]
	for _, v := range vals[1:] {
		if v > maxVal {
			maxVal = v
		}
	}
	return maxVal
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func solve() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	var n int
	scanner.Scan()
	fmt.Sscanf(scanner.Text(), "%d", &n)

	a := make([]int, 3)
	b := make([]int, 3)

	for i := 0; i < 3; i++ {
		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%d", &a[i])
	}
	for i := 0; i < 3; i++ {
		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%d", &b[i])
	}

	val1 := maxInt(0, a[0]-b[0]-b[2], a[1]-b[0]-b[1], a[2]-b[2]-b[1])
	val2 := minInt(a[0], b[1]) + minInt(a[1], b[2]) + minInt(a[2], b[0])

	fmt.Println(val1, val2)
}

func main() {
	solve()
}

